import type { SerializedError } from '../control/errors.js'
import { isRecord } from '../control/value-guards.js'

export const RUNTIME_COMMAND_TYPES = ['benchkit:metrics:start', 'benchkit:metrics:stop', 'benchkit:shutdown'] as const

/** Target-runtime command names carried over Node.js IPC. */
export type RuntimeCommandType = (typeof RUNTIME_COMMAND_TYPES)[number]

/** Command sent from the control agent to a target runtime. */
export interface RuntimeCommand {
  /** Runtime operation name. */
  type: RuntimeCommandType

  /** Correlation identifier generated by the control agent. */
  id: string

  /** Operation-specific request data. */
  payload?: unknown
}

/** Correlated target-runtime response sent over Node.js IPC. */
export interface RuntimeResponse {
  /** Runtime response discriminator. */
  type: 'benchkit:response'

  /** Correlation identifier copied from the command. */
  id: string

  /** Whether the runtime operation succeeded. */
  status: 'ok' | 'error'

  /** Operation-specific success data. */
  payload?: unknown

  /** Serialized failure data when `status` is `'error'`. */
  error?: SerializedError
}

/** Unsolicited IPC message announcing target network readiness. */
export interface RuntimeReady {
  /** Runtime readiness discriminator. */
  type: 'benchkit:ready'

  /** Target endpoint data and optional target-specific metadata. */
  payload: {
    /** TCP port on which the target is listening. */
    port: number

    /** Target-specific readiness metadata. */
    [key: string]: unknown
  }
}

export function isRuntimeCommand(value: unknown): value is RuntimeCommand {
  return (
    isRecord(value) && typeof value.id === 'string' && RUNTIME_COMMAND_TYPES.includes(value.type as RuntimeCommandType)
  )
}

export function isRuntimeResponse(value: unknown): value is RuntimeResponse {
  return isRecord(value) && value.type === 'benchkit:response' && typeof value.id === 'string'
}
